def nthSuperUglyNumber( n: int, primes: list[int]) -> int:
    output = [1]
    minPQ = []

    for p in primes:
        minPQ.append((p, 0, p))

    while len(output) < n:
        value, idx, prime = minPQ.pop(0)
        if value != output[-1]:
            output.append(value)
            minPQ.append((output[idx + 1] * prime, idx + 1, prime))

    return output[n - 1]
